1	// Acceptance test for the change request:
2	//   "When I open a project I want to see its invoices. Show me what they add up to. Let me add a
3	//    new invoice for an amount."
4	//
5	// Opening a project (project-open-<id> from the projects list) lands on that project's detail page.
6	// The detail page lists THAT project's invoices, each showing its amount, and shows what they add
7	// up to (project-invoices-total). A new invoice is added by giving an amount; once added it joins
8	// the same invoices list, the total grows by that amount, and both survive a fresh load.
9	//
10	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
11	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
12	// `invoices` honours { id, amount, projectId }.
13	import { test, expect, type Page, type Locator } from '@playwright/test';
14	import { resetAndSeed } from '../support/seed';
15	
16	const invoiceRows = (page: Page) => page.locator('[data-testid^="invoice-row-"]');
17	
18	// A money value may be rendered with a currency symbol, grouping or decimals ($1,200.00) or bare
19	// (1200). Assert the amount it carries is PRESENT, so the test binds to "what they add up to"
20	// rather than to one presentation. The digits used below are chosen so no amount or total is a
21	// substring of another.
22	const digits = (n: number) => String(n);
23	
24	async function expectAmount(cell: Locator, n: number): Promise<void> {
25	  await expect(cell).toContainText(digits(n));
26	}
27	
28	test.describe('Project invoices', () => {
29	  test('opening a project from the list lands on its detail page', async ({ page }) => {
30	    await resetAndSeed({
31	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
32	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
33	      invoices: [],
34	    });
35	
36	    await page.goto('/projects');
37	    await expect(page.getByTestId('project-row-1')).toBeVisible();
38	
39	    // Opening the project is a navigation, not a flag: following it lands on that project's own
40	    // detail page.
41	    const open = page.getByTestId('project-open-1');
42	    await expect(open).toBeVisible();
43	    await open.click();
44	
45	    await expect(page).toHaveURL(/\/projects\/1$/);
46	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
47	  });
48	
49	  test('the detail page lists the project invoices with their amounts and what they add up to', async ({
50	    page,
51	  }) => {
52	    await resetAndSeed({
53	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
54	      projects: [
55	        { id: 1, name: 'Website Redesign', clientId: 1 },
56	        { id: 2, name: 'Mobile App', clientId: 1 },
57	      ],
58	      invoices: [
59	        { id: 1, amount: 100, projectId: 1 },
60	        { id: 2, amount: 250, projectId: 1 },
61	        { id: 3, amount: 50, projectId: 1 },
62	        // An invoice on a DIFFERENT project must not show here, nor count toward this total.
63	        { id: 4, amount: 999, projectId: 2 },
64	      ],
65	    });
66	
67	    await page.goto('/projects/1');
68	
69	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
70	    await expect(page.getByTestId('project-invoices-table')).toBeVisible();
71	
72	    // Only this project's three invoices are shown, each carrying its own amount.
73	    await expect(invoiceRows(page)).toHaveCount(3);
74	    await expectAmount(page.getByTestId('invoice-row-1').getByTestId('invoice-amount'), 100);
75	    await expectAmount(page.getByTestId('invoice-row-2').getByTestId('invoice-amount'), 250);
76	    await expectAmount(page.getByTestId('invoice-row-3').getByTestId('invoice-amount'), 50);
77	
78	    // The other project's invoice is nowhere on this page.
79	    await expect(page.getByTestId('invoice-row-4')).toHaveCount(0);
80	    await expect(page.getByTestId('project-detail-page')).not.toContainText('999');
81	
82	    // And the page shows what they add up to: 100 + 250 + 50 = 400.
83	    await expectAmount(page.getByTestId('project-invoices-total'), 400);
84	  });
85	
86	  test('a project with no invoices shows an empty list that adds up to zero', async ({ page }) => {
87	    await resetAndSeed({
88	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
89	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
90	      invoices: [],
91	    });
92	
93	    await page.goto('/projects/1');
94	
95	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
96	    await expect(invoiceRows(page)).toHaveCount(0);
97	    // Nothing invoiced yet, so what they add up to is zero.
98	    await expectAmount(page.getByTestId('project-invoices-total'), 0);
99	  });
100	
101	  test('adding a new invoice for an amount shows it and grows the total', async ({ page }) => {
102	    await resetAndSeed({
103	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
104	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
105	      invoices: [{ id: 1, amount: 100, projectId: 1 }],
106	    });
107	
108	    await page.goto('/projects/1');
109	    await expect(invoiceRows(page)).toHaveCount(1);
110	    await expectAmount(page.getByTestId('project-invoices-total'), 100);
111	
112	    // Add a new invoice by giving it an amount.
113	    await expect(page.getByTestId('invoice-form')).toBeVisible();
114	    await page.getByTestId('invoice-form-amount').fill('300');
115	    await page.getByTestId('invoice-form-submit').click();
116	
117	    // The new invoice joins the same list. Its id is assigned by the server, so locate the new row
118	    // by the amount it carries rather than by a known id.
119	    const addedRow = invoiceRows(page).filter({
120	      has: page.getByTestId('invoice-amount').getByText('300', { exact: false }),
121	    });
122	    await expect(addedRow).toHaveCount(1);
123	
124	    // Both invoices are now listed, and the total has grown to 100 + 300 = 400.
125	    await expect(invoiceRows(page)).toHaveCount(2);
126	    await expectAmount(page.getByTestId('project-invoices-total'), 400);
127	
128	    // And it survives a fresh load from the server.
129	    await page.reload();
130	    await expect(invoiceRows(page)).toHaveCount(2);
131	    await expect(
