    expect(paidRecordsFor(2, 250)).toHaveLength(1);
    expect(auditLines()).toHaveLength(2);
  });

  test('an invoice seeded as paid is shown as paid from the start', async ({ page }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
      invoices: [{ id: 1, amount: 100, projectId: 1, status: 'PAID' }],
    });

    await page.goto('/projects/1');

    // The status reflects the persisted state: this invoice is already paid.
    await expect(statusOf(page, 1)).toHaveText(PAID);

    // Merely loading a paid invoice records nothing — the record is kept when the marking happens,
    // not on every view.
    expect(auditLines()).toEqual([]);
  });
});

